import { readFileSync } from "node:fs";
import path from "node:path";

/**
 * Committed git commit dates for sitemap lastmod.
 * Regenerated by scripts/generate-content-lastmod.mjs.
 * Never use the build clock — Google ignores lastmod when every URL shares a deploy timestamp.
 */
type LastmodMap = Record<string, string>;

let cached: LastmodMap | null = null;

function loadMap(): LastmodMap {
  if (cached) {
    return cached;
  }

  const filePath = path.join(
    /* turbopackIgnore: true */ process.cwd(),
    "src",
    "lib",
    "seo",
    "content-lastmod.json",
  );
  cached = JSON.parse(readFileSync(filePath, "utf8")) as LastmodMap;
  return cached;
}

/** Latest YYYY-MM-DD among the committed lastmod values for these source files. */
export function contentLastmod(...relPaths: string[]): string {
  const map = loadMap();
  let latest = "";

  for (const relPath of relPaths) {
    const date = map[relPath];
    if (!date || !/^\d{4}-\d{2}-\d{2}$/.test(date)) {
      throw new Error(
        `No committed lastmod for ${relPath}. Run node scripts/generate-content-lastmod.mjs.`,
      );
    }
    if (date > latest) {
      latest = date;
    }
  }

  if (!latest) {
    throw new Error("contentLastmod requires at least one path.");
  }

  return latest;
}

/** Calendar date in Australia/Sydney. Sitemap lastmod uses this so a 07:00 AEDT edit stays on that day. */
export function sydneyDate(date: Date): string {
  return new Intl.DateTimeFormat("en-CA", {
    timeZone: "Australia/Sydney",
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  }).format(date);
}

export function latestContentDate(dates: string[]): string {
  let latest = "";
  for (const date of dates) {
    if (/^\d{4}-\d{2}-\d{2}$/.test(date) && date > latest) {
      latest = date;
    }
  }
  if (!latest) {
    throw new Error("latestContentDate requires at least one YYYY-MM-DD value.");
  }
  return latest;
}
